                with os.fdopen(fd, "w", encoding="utf-8") as target:
                    json.dump(
                        {"version": 1, "entries": entries},
                        target,
                        ensure_ascii=False,
                        allow_nan=False,
                        separators=(",", ":"),
                    )
                    target.write("\n")
                    target.flush()
                    os.fsync(target.fileno())
                os.replace(temporary_name, self.path)
                try:
                    directory_fd = os.open(parent, os.O_RDONLY)
                    try:
